T("The Science of Snap and Gloss", "Advanced",
  ["Chocolate's snap and gloss come from Form V cocoa butter crystals, built by tempering.",
   "Six crystal forms exist; only Form V is stable, glossy, and snappy.",
   "Bloom is Form V reverting to unstable forms — still edible, just unattractive.",
   "Conching (long grinding) rounds flavor by driving off volatile acids.",
   "Particle size under 20 microns reads as smooth to the tongue."],
  ["Control temperature precisely through the tempering curve.",
   "Avoid moisture at every stage; water disrupts crystal formation.",
   "Age finished bars 2+ weeks; flavor continues to develop.",
   "Measure particle size by mouthfeel: gritty means more conching needed."],
  "Signature chocolate science: the generator explains every texture in crystal terms.",
  {"variant":"convert","pairs":[["Form V melt point","34","C","F","1.8"],["Smooth particle size","20","microns","mm","0.001"]]}),
T("Chocolate Factory Tour Knowledge", "Advanced",
  ["Industrial chocolate: roasting, winnowing, grinding, conching (hours to days), tempering, molding.",
   "Conching time is a quality lever: longer conching, smoother and mellower chocolate.",
   "Lecithin (a tiny amount) reduces viscosity so chocolate flows into molds.",
   "Dutching (alkalizing cocoa) darkens color and mellows flavor.",
   "Bean sourcing and fermentation quality matter more than any machine."],
  ["Tour a factory if you can; seeing conches demystifies chocolate.",
   "Ask about conch time and bean origin — the answers reveal quality priorities.",
   "Compare industrial and craft bars side by side.",
   "Support makers who publish their sourcing."],
  "Signature factory decoder: the generator translates label claims into process realities.",
  {"variant":"ratio","a":["craft conch time, hours","72"],"b":["industrial conch time, hours","8"]}),
