T("Commercial vs Artisan", "Advanced",
  ["Commercial ice cream optimizes for shelf life and cost: more air, more stabilizers.",
   "Artisan makers optimize for flavor: less air, fresh ingredients, short ingredient lists.",
   "Overrun is the tell: dense artisan pints feel heavy; airy commercial tubs feel light.",
   "Read labels: cream, milk, sugar, and flavor vs. a paragraph of gums and syrups.",
   "Price per ounce of actual food (not air) often favors artisan."],
  ["Compare a premium and a budget vanilla side by side, weighed.",
   "Note melt behavior: fast, foamy melt suggests high overrun.",
   "Taste for flavor intensity per spoonful.",
   "Decide what matters to you: price, purity, or intensity — then buy accordingly."],
  "Signature label decoder: the generator translates ice cream labels into plain language.",
  {"variant":"ratio","a":["artisan overrun, %","30"],"b":["economy overrun, %","100"]}),
