   "Fat-soluble flavors (spices, herbs, tea) infuse best in warm cream.",
   "Acidic additions (citrus, passion fruit) go in after churning to avoid curdling.",
   "Layer flavors: a base note (vanilla), a middle (fruit), a top (herb or spice).",
