T("The Maillard Reaction", "Foundations",
  ["The Maillard reaction browns proteins and sugars together, creating hundreds of flavor compounds.",
   "It starts around 140 C; boiling water (100 C) never triggers it — that is why steamed meat tastes flat.",
   "Dry surfaces brown faster; pat meat dry before searing.",
   "A little sugar or high heat accelerates it; crowding the pan prevents it (steam).",
   "Nearly all 'roasted' flavor — bread crust, seared steak, coffee — is Maillard."],
  ["Pat proteins dry; use high heat and do not crowd.",
   "Sear in batches if needed; steaming is the enemy of browning.",
   "Deglaze the browned bits (fond) into sauces.",
   "Taste the difference: seared vs. steamed side by side."],
  "Signature Maillard model: the generator predicts browning from heat, moisture, and time.",
  {"variant":"convert","pairs":[["Maillard onset","140","C","F","1.8"],["Boiling point","100","C","F","1.8"]]}),
